import React from 'react';
import PropTypes from 'prop-types';
import './ResortList.css'; // Assuming you have a CSS file for additional styles

const ResortList = ({ resorts = [], onResortClick }) => {
  if (!Array.isArray(resorts)) {
    console.error('Resorts is not an array:', resorts);
    return <div className="error-message">Unexpected data format</div>;
  }

  return (
    <div className="resort-list-container">
      {resorts.length === 0 ? (
        <p className="no-resorts-message">No resorts available</p>
      ) : (
        <ul className="resort-list">
          {resorts.map(resort => (
            <li
              key={resort.id}
              className="resort-item"
              onClick={() => onResortClick(resort)}
            >
              {resort.name}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

// PropTypes for better type checking
ResortList.propTypes = {
  resorts: PropTypes.array,
  onResortClick: PropTypes.func.isRequired,
};

export default ResortList;
